// 角度定義：每個「可以檢查的角度」用哪幾個關鍵點計算
// routine.json 的每一步只要寫這裡的代號（例如 rightShoulderRaise）
//
// ★ 所有左右一律指「練習者自己的」左右。
//   （鏡像模式下，程式會先把示範者的骨架左右翻轉，再算目標角度，你不用自己換算。）
//
// 欄位說明：
//   name   畫面上顯示的中文名稱
//   side   "left" / "right" / "center"：這是身體哪一側的角度（用來檢查有沒有複製貼上忘了改）
//   type   "joint"   = 三點夾角：在第 2 個點量 0～180 度（180 = 打直）
//          "segment" = 肢段方向：從第 1 點指向第 2 點，相對「直立朝上」的角度
//          "drop"    = 軀幹下降：髖部比前幾秒內最高的位置低了多少（軀幹長度的 %，0 = 站直），points 固定 ["midHip", "midShoulder"]
//          "joint3d" = 3D 夾角：和 joint 一樣，但用 3D 估計；eitherSide: true = 取左右兩側中比較彎的一側
//          "gap"     = 高低差：第 1 點比第 2 點低多少（軀幹長度的 %），第 1 點較低為正
//   minVisibility（可省略）這個角度自己的可信度門檻，比 settings.json 的 judge.minVisibility 高時才有作用
//                      （0 = 朝正上方，往自己右側傾為正、往左側傾為負，-180～180）
//   group  部位分組，用來整組調整容許角度（settings.json 的 judge.groupAdjustDeg）：
//          "upper" 上半身、"lower" 下半身（不含踝）、"ankle" 有用到踝關節、"trunk" 軀幹
//   points 關鍵點名稱（joint 填 3 個、segment 填 2 個）
//          最後一個點是「會動的那一端」，未達標時那段肢段會變紅
//          可用名稱見 src/pose/landmarks.ts，另有 midShoulder（兩肩中點）、midHip（兩髖中點）
// ═══════════════════════════════════════════════
{
  "angles": {
    // ── 手臂 ──
    // 上臂抬舉：軀幹與上臂的夾角。0 = 手垂在身側，90 = 側平舉，180 = 舉過頭
    "leftShoulderRaise":  { "name": "左上臂抬舉", "group": "upper", "side": "left",  "type": "joint", "points": ["leftHip", "leftShoulder", "leftElbow"] },
    "rightShoulderRaise": { "name": "右上臂抬舉", "group": "upper", "side": "right", "type": "joint", "points": ["rightHip", "rightShoulder", "rightElbow"] },

    // 手肘：180 = 手臂打直
    "leftElbow":  { "name": "左手肘", "group": "upper", "side": "left",  "type": "joint", "points": ["leftShoulder", "leftElbow", "leftWrist"] },
    "rightElbow": { "name": "右手肘", "group": "upper", "side": "right", "type": "joint", "points": ["rightShoulder", "rightElbow", "rightWrist"] },

    // ── 下肢 ──
    // 髖（軀幹與大腿）：180 = 站直，腿往外張開時變小（正面拍攝看不太出往前抬腿）
    "leftHip":  { "name": "左髖", "group": "lower", "side": "left",  "type": "joint", "points": ["leftShoulder", "leftHip", "leftKnee"] },
    "rightHip": { "name": "右髖", "group": "lower", "side": "right", "type": "joint", "points": ["rightShoulder", "rightHip", "rightKnee"] },

    // 膝：180 = 腿打直。注意：腳踝被身體擋住時（例如往後跨的弓箭步），姿態偵測會亂猜出 2～30 度這種不可能的角度；
    // 需要時可加 "minVisibility": 0.7 提高門檻，但會讓腳靠近畫面下緣的人比較常「看不清楚」（2026-10-25 試過，第 1、3、10 步受影響，已拿掉）
    "leftKnee":  { "name": "左膝", "group": "ankle", "side": "left",  "type": "joint", "points": ["leftHip", "leftKnee", "leftAnkle"] },
    "rightKnee": { "name": "右膝", "group": "ankle", "side": "right", "type": "joint", "points": ["rightHip", "rightKnee", "rightAnkle"] },

    // 兩腿張開角：0 = 併腿
    "legSpread": { "name": "兩腿張開", "group": "lower", "side": "center", "type": "joint", "points": ["leftKnee", "midHip", "rightKnee"] },

    // ── 軀幹 ──
    // 軀幹側彎：0 = 直立，往自己右側彎為正、左側為負
    "trunkTilt": { "name": "軀幹側彎", "group": "trunk", "side": "center", "type": "segment", "points": ["midHip", "midShoulder"] },

    // 軀幹下降（type "drop"）：髖部比前幾秒內最高的位置低了多少，以軀幹長度的 % 表示（0 = 站直）。
    // 從正面拍時，往後跨的弓箭步看不出腿的角度，但身體下降很明顯（使用者實測：站直約 2%，蹲下 60～80%）
    "torsoDrop": { "name": "軀幹下降", "group": "trunk", "side": "center", "type": "drop", "points": ["midHip", "midShoulder"] },

    // 前膝（3D，type "joint3d"）：用 MediaPipe 的 3D 估計量膝蓋夾角，取兩腳中比較彎的一腳（不用管哪一腳在前）。
    // 正面拍時大腿朝鏡頭，2D 看起來是直的；3D 才量得出彎曲（使用者實測：弓箭步約 86～110 度，站直約 150～160 度）
    "frontKnee3d": { "name": "前膝", "group": "lower", "side": "center", "type": "joint3d", "points": ["leftHip", "leftKnee", "leftAnkle"], "eitherSide": true },

    // 兩膝高低差（type "gap"）：左膝比右膝低多少（軀幹長度的 %），左膝較低為正。
    // 弓箭步時往後跨的那隻腳膝蓋比較低，用來分辨是哪一腳往後（使用者實測：左腳在後 +51%、右腳在後 -42%）
    "kneeGap": { "name": "後腳", "group": "lower", "side": "center", "type": "gap", "points": ["leftKnee", "rightKnee"] }
  }
}
